#include <strings.h>

//WannaCry kill-switch domains
static const char* domain_lst[] = {
"iuqerfsodp9ifjaposdfjhgosurijfaewrwergwea.com",
"ifferfsodp9ifjaposdfjhgosurijfaewrwergwea.com",
"ayylmaotjhsstasdfasdfasdfasdfasdfasdfasdf.com",
"iuqssfsodp9ifjaposdfjhgosurijfaewrwergwea.com",
"iuqerfsodp9ifjaposdfjhgosurijfaewrwergweb.com",
};

/**
 * Return 1 if the HTTP Host is a listed domain or one of its subdomains
 * (e.g., "www." that the malware requests), otherwise 0.
 * The Host is compared case-insensitively, after removing a ":port" suffix,
 * surrounding white space and a trailing dot.
 */
static inline int em_check_WannaCry(const char * str){
	const char *end, *c;
	size_t len, dlen;
	int i;
	const int length = sizeof( domain_lst ) / sizeof( domain_lst[0] );

	if( str == NULL )
		return 0;
	while( *str == ' ' || *str == '\t' )
		str ++;
	//host name ends at ':' (port) or at white space
	for( end = str; *end != '\0' && *end != ':' && *end != ' ' && *end != '\t' && *end != '\r' && *end != '\n'; end++ )
		;
	if( end > str && end[-1] == '.' )
		end --;
	len = end - str;

	for( i=0; i<length; i++ ){
		dlen = strlen( domain_lst[i] );
		if( len < dlen )
			continue;
		c = end - dlen;
		//the domain itself, or a subdomain: the domain is preceded by a dot
		if( strncasecmp( c, domain_lst[i], dlen ) == 0 && (c == str || c[-1] == '.') )
			return 1;
	}
	return 0;
}
